; ==================================================================
; Bank 81 ($51) — BATTLE SCREEN + TURN EXECUTION
; ==================================================================
; file offset $144000.  Called from bank80 fn2 (the battle sequencer):
;   bank80 state 0  -> bank81 fn0   (open/init the battle screen)
;   bank80 state 12 -> bank81 fn12  (run the turn)
;   bank80          -> bank81 fn14  (per-action resolution)
;
; This bank owns the battle *presentation and turn execution*: it loads
; the battle tilesets into VRAM, draws the monsters, and steps through
; each action's animation/damage resolution. It shares WRAM with bank80's
; command phase — notably it reuses $D9F4 as its own RST $00 state index
; and INCs the outer scene counter $D9EC when a phase finishes.
;
; Shared WRAM (see wram.asm BATTLE SYSTEM section):
;   $D9F4  RST $00 state index for fn12/fn14 (reused per-function)
;   $D9EC  outer fn2 scene counter (INC'd on completion)
;   $C863  side flags (bit1 = player-2 side)
;   $C86C  link-connected flag
;   $DB74/$DB75  per-side active monster counts
;   $CAC0/$CB0C  current actor slot + coordinate table
;
; Notable functions (decoded):
;   fn0  $423C  battle-screen INIT: prep party ($4243) then load tilesets
;               to VRAM $9600/$8800/$8D00/$8B00 via ROM0 $18A2 (helper at
;               $402B, also reachable as the pre-table routine)
;   fn12 $5576  TURN driver — 18-state machine on $D9F4
;   fn14 $5C34  ACTION resolution — 37-state machine on $D9F4
;   fn16 $6920  actor/side helper (reads $DB74/$DB75 by side)
;
; Function table ($4001, 21 entries; fn18-20 point into ROM0 and may be
; unused padding). The RST $10 handler indexes it by function number.
; ------------------------------------------------------------------
; RST $10 targets:
;   fn0  -> $423C   battle init
;   fn1  -> $43F2
;   fn2  -> $4A94
;   fn3  -> $4BE6
;   fn4  -> $4CB1
;   fn5  -> $4D14
;   fn6  -> $4E5C
;   fn7  -> $4FA8
;   fn8  -> $50F4
;   fn9  -> $5248
;   fn10 -> $46A8
;   fn11 -> $44A7
;   fn12 -> $5576
;   fn13 -> $5B32
;   fn14 -> $5C34
;   fn15 -> $5378
;   fn16 -> $6920
;   fn17 -> $5567
;   fn18 -> $1721  [ROM0]
;   fn19 -> $36C8  [ROM0]
;   fn20 -> $2300  [ROM0]
; ==================================================================
SECTION "bank81",ROMX[$4000],BANK[$51]

