; --- STAT COPY-IN: load one monster's stats from its $CAC1 record into
;     the parallel 16-bit battle working arrays. HL walks the source
;     record ($CAC1 slot); each $469A call copies one 16-bit stat for this
;     monster (indexed by slot) into the next array:
;       $DBA3, $DBB3, $DBC3, $DBD3, $DBE3, $DBF3, $DC03, $DC13, $DC23
;     (each array = 8 slots × 2 bytes). Combat then reads these $DB.. arrays
;     — NOT $CAC1 directly. HP working copy = $DBA3. (Results are written
;     back into $CAC1 and saved to SRAM at battle end, bank80 state 17.)
