;   Copies $D9FD→$D929, then for each slot C (0..$DB74-1) resolves its
;   $CAC1 record ptr (base $CB0B via ROM0 $25F8) and runs helpers
;   ($4ABE/$4AEE) — looks like a positions/sprites refresh for the roster.
