; fn5..fn8 — a FAMILY of per-monster status-array writers (variants).
;   All four share this prologue: derive the acting monster's index from
;   $DB88 (AND $04 = side, OR $03 = base), publish it to $DB4C, and index
;   the per-monster array at $DB8B (stride 8). They then write/clear a set
;   of that monster's 8-byte battle-state fields (bytes at +0,+8,+$10,…).
;   The four differ in which fields/values they set — used at different
;   points of the attack pipeline (e.g. arm/clear status, defend, etc.).
; fn5 ($4D14):
Bank81_fn5:  ; $4D14
    LD B,$00                             ; $4D14 [06 00]
    LD A,($DB88)                         ; $4D16 [FA 88 DB]  ; WRAM[$DB88]
    AND $04                              ; $4D19 [E6 04]
    OR $03                               ; $4D1B [F6 03]
    LD ($DB4C),A                         ; $4D1D [EA 4C DB]  ; -> WRAM[$DB4C]
    LD HL,$DB8B                          ; $4D20 [21 8B DB]
    ADD A,L                              ; $4D23 [85]
